{"kind": "table", "icon": "📋", "head": "पाटलिपुत्र के प्राचीन नाम", "eq": "एक नगर, कई नाम", "rows": [["नाम", "अर्थ / कारण"], ["पाटलिग्राम", "सबसे पुराना नाम — जब यह एक गाँव था"], ["पाटलिपुत्र", "पाटल (गुलाब जैसे फूल) के पेड़ों के कारण"], ["पुष्पपुर", "पुष्प = फूल · फूलों का नगर"], ["कुसुमपुर", "कुसुम = फूल · फूलों का नगर"], ["पटना", "आज का नाम — 'पत्तन' (नगर) या पाटन देवी से"]], "say": "पाटलिपुत्र के, कई प्राचीन नाम मिलते हैं। सबसे पुराना नाम है, पाटलिग्राम, जब यह एक गाँव था। फिर पाटलिपुत्र। पाटल, एक फूल का नाम है, गुलाब जैसा। कहा जाता है, कि यहाँ पाटल के पेड़, बहुत थे। पाठ में, इसके दो और नाम बताए गए हैं, पुष्पपुर, और कुसुमपुर। पुष्प और कुसुम, दोनों का अर्थ है, फूल। यानी फूलों का नगर। ये दोनों नाम, परीक्षा के लिए बहुत ज़रूरी हैं। और आज का नाम है, पटना, जो शायद पत्तन शब्द से, या यहाँ की पाटन देवी के नाम से बना है।"},
{"kind": "eq", "icon": "📚", "head": "विद्या का केंद्र: राजशेखर का कथन", "words": "प्रसिद्ध कवि राजशेखर ने अपने ग्रंथ 'काव्यमीमांसा' में लिखा है —", "eq": "पाटलिपुत्र में शास्त्रकारों की परीक्षा होती थी", "note": "यहाँ परीक्षा देकर बड़े-बड़े विद्वानों ने ख्याति (प्रसिद्धि) पाई", "say": "पाटलिपुत्र, केवल राजनीति का ही नहीं, विद्या का भी बहुत बड़ा केंद्र था। प्रसिद्ध कवि राजशेखर ने, अपने ग्रंथ काव्यमीमांसा में लिखा है, कि पाटलिपुत्र में, शास्त्रकारों की परीक्षा होती थी। यानी देश के बड़े-बड़े विद्वान, अपनी विद्या की परीक्षा देने, यहाँ आते थे। और यहाँ परीक्षा में सफल होकर ही, उन्हें ख्याति, यानी प्रसिद्धि मिलती थी। सोचिए, जैसे आज, बड़ी परीक्षाएँ पास करके, लोग नाम कमाते हैं, वैसे ही उस समय, पाटलिपुत्र की परीक्षा पास करना, सबसे बड़े सम्मान की बात थी। राजशेखर और काव्यमीमांसा, ये दोनों नाम याद रखिए।"},
{"kind": "table", "icon": "📋", "head": "पाटलिपुत्र में परीक्षित विद्वान", "eq": "राजशेखर के अनुसार — ये यहाँ परीक्षा देकर प्रसिद्ध हुए", "rows": [["विद्वान", "किसके लिए प्रसिद्ध"], ["वर्ष और उपवर्ष", "महान आचार्य (गुरु)"], ["पाणिनि", "संस्कृत व्याकरण 'अष्टाध्यायी' के रचयिता"], ["पिंगल", "छंदशास्त्र के रचयिता"], ["व्याडि", "व्याकरण के विद्वान"], ["वररुचि", "व्याकरण के वार्तिककार"], ["पतंजलि", "'महाभाष्य' के रचयिता"]], "say": "राजशेखर ने, उन विद्वानों के नाम भी बताए हैं, जिनकी परीक्षा पाटलिपुत्र में हुई, और जो यहाँ से प्रसिद्ध हुए। वर्ष और उपवर्ष, जो महान आचार्य थे। पाणिनि, जिन्होंने संस्कृत व्याकरण का महान ग्रंथ, अष्टाध्यायी रचा। पिंगल, जिन्होंने छंदशास्त्र रचा। व्याडि, जो व्याकरण के विद्वान थे। वररुचि, जो व्याकरण के वार्तिककार थे। और पतंजलि, जिन्होंने महाभाष्य की रचना की। सोचिए, संस्कृत व्याकरण के, सबसे बड़े नाम, पाणिनि, वररुचि और पतंजलि, तीनों का रिश्ता, हमारे पटना से है।"},
{"kind": "content", "icon": "🪷", "head": "दामोदर गुप्त और 'कुट्टनीमतम्'", "points": ["आठवीं सदी में कश्मीर के कवि दामोदर गुप्त हुए", "उन्होंने अपने काव्य 'कुट्टनीमतम्' में पाटलिपुत्र का वर्णन किया", "उन्होंने इसे पृथ्वी का तिलक और सरस्वती (विद्या) का घर बताया", "यानी उस समय भी दूर कश्मीर तक पाटलिपुत्र की विद्या की धूम थी"], "say": "पाठ में, एक और कवि का नाम आता है। आठवीं सदी में, कश्मीर में, दामोदर गुप्त नाम के कवि हुए। उन्होंने, अपने काव्य कुट्टनीमतम् में, पाटलिपुत्र का सुंदर वर्णन किया है। उन्होंने इसे, पृथ्वी का तिलक, और सरस्वती का, यानी विद्या का घर बताया। सोचिए, कश्मीर यहाँ से कितनी दूर है। पर वहाँ का कवि भी, पाटलिपुत्र की महिमा गा रहा है। यानी उस समय, पूरे भारत में, पाटलिपुत्र की विद्या की धूम थी। दामोदर गुप्त, और कुट्टनीमतम्, ये भी परीक्षा के लिए याद रखिए।"},
{"kind": "content", "icon": "⏳", "head": "मध्यकाल और बाद का समय", "points": ["मध्यकाल में पाटलिपुत्र का वैभव कुछ समय के लिए घट गया", "फिर मुग़ल काल में इसका दोबारा उद्धार (विकास) हुआ", "अंग्रेज़ों के शासन में भी यह एक महत्वपूर्ण नगर बना रहा", "1912 में बिहार अलग प्रांत बना — पटना उसकी राजधानी", "पाठ: समय के उतार-चढ़ाव के बाद भी नगर का गौरव बना रहा"], "say": "पाठ आगे बताता है, कि मध्यकाल में, पाटलिपुत्र का वैभव, कुछ समय के लिए घट गया, और यह नगर, पहले जैसा प्रसिद्ध नहीं रहा। फिर मुग़ल काल में, इसका दोबारा उद्धार हुआ, यानी फिर से विकास हुआ। अंग्रेज़ों के शासन में भी, यह एक महत्वपूर्ण नगर बना रहा। और उन्नीस सौ बारह में, जब बिहार, बंगाल से अलग प्रांत बना, तब पटना, उसकी राजधानी बना। पाठ का भाव यह है, कि समय के इतने उतार-चढ़ाव के बाद भी, इस नगर का गौरव बना रहा। कोई भी नगर, जो ढाई हज़ार साल तक, लगातार बसा रहे, वह सचमुच ख़ास होता है।"},
{"kind": "content", "icon": "🪯", "head": "सिख धर्म का तीर्थ", "points": ["सिखों के दसवें गुरु — गुरु गोबिंद सिंह जी — का जन्म यहीं हुआ", "उनके जन्म-स्थान पर प्रसिद्ध गुरुद्वारा: तख़्त श्री हरिमंदिर जी (पटना साहिब)", "संस्कृत: 'गुरुगोविन्दसिंहस्य जन्मस्थानम्'", "यह सिख धर्म के लोगों का बड़ा तीर्थस्थान है", "देश-विदेश से श्रद्धालु यहाँ आते हैं"], "say": "पाटलिपुत्र का, एक और बड़ा गौरव है। सिखों के दसवें गुरु, गुरु गोबिंद सिंह जी का जन्म, यहीं पटना में हुआ। उनके जन्म-स्थान पर, प्रसिद्ध गुरुद्वारा है, तख़्त श्री हरिमंदिर जी, जिसे हम पटना साहिब कहते हैं। पाठ में कहा गया है, कि यह स्थान, सिख धर्म के लोगों का, बड़ा तीर्थस्थान है। देश और विदेश से, श्रद्धालु यहाँ आते हैं। यह प्रश्न, लगभग हर साल पूछा जाता है, कि पटना में, किस सिख गुरु का जन्म हुआ था। उत्तर है, दसवें गुरु, गुरु गोबिंद सिंह जी का।"},
{"kind": "table", "icon": "📋", "head": "आधुनिक पटना के दर्शनीय स्थल", "eq": "पाठ में आए नाम", "rows": [["संस्कृत नाम", "हिंदी / विशेष बात"], ["सङ्ग्रहालयः", "संग्रहालय (पटना म्यूज़ियम)"], ["उच्चन्यायालयः", "हाई कोर्ट"], ["सचिवालयः", "सचिवालय (सरकार का कार्यालय)"], ["गोलगृहम्", "गोलघर — अनाज रखने का विशाल गोल भंडार"], ["तारामण्डलम्", "तारामंडल (प्लैनेटेरियम)"], ["जैविकोद्यानम्", "चिड़ियाघर (संजय गांधी जैविक उद्यान)"], ["मौर्यकालिक-अवशेषः", "कुम्हरार के मौर्यकालीन अवशेष"], ["महावीरमन्दिरम्", "स्टेशन के पास का प्रसिद्ध हनुमान मंदिर"]], "say": "पाठ में, आधुनिक पटना के, दर्शनीय स्थलों के नाम भी दिए गए हैं। संस्कृत नाम, और उनके अर्थ देखिए। सङ्ग्रहालयः, यानी संग्रहालय, पटना म्यूज़ियम। उच्चन्यायालयः, यानी हाई कोर्ट। सचिवालयः, यानी सचिवालय, जहाँ सरकार का कार्यालय है। गोलगृहम्, यानी गोलघर, जो अनाज रखने का, विशाल गोल भंडार है। तारामण्डलम्, यानी तारामंडल। जैविकोद्यानम्, यानी चिड़ियाघर। मौर्यकालिक अवशेष, यानी कुम्हरार के, मौर्यकालीन अवशेष। और महावीरमन्दिरम्, यानी स्टेशन के पास का, प्रसिद्ध हनुमान मंदिर। हमारे धामुचक के बच्चों ने, इनमें से कई जगहें, अपनी सैर में देखी थीं।"},
{"kind": "eq", "icon": "🌉", "head": "गाँधी सेतु", "words": "गङ्गायाः उपरि निर्मितः गान्धीसेतुः", "eq": "एशिया महादेश के सबसे लंबे पुलों में से एक", "note": "यह पटना को उत्तर बिहार (हाजीपुर) से जोड़ता है", "say": "पाठ में, एक और गौरव की बात कही गई है। गंगा नदी के ऊपर बना, गाँधी सेतु। पाठ के अनुसार, यह एशिया महादेश का, सबसे लंबा पुल है। यह पुल, पटना को, गंगा के उस पार, उत्तर बिहार के हाजीपुर से जोड़ता है। जब यह बना था, तब यह नदी पर बना, सबसे लंबा पुल था। सेतु शब्द का अर्थ है, पुल। यह प्रश्न भी पूछा जाता है, कि गाँधी सेतु, किस नदी पर है। उत्तर है, गंगा नदी पर।"},
{"kind": "content", "icon": "🛕", "head": "पाटन देवी: नगर की रक्षिका", "points": ["पटना में पाटन देवी (पटन देवी) का प्राचीन मंदिर है", "लोग इन्हें नगर की रक्षा करने वाली देवी मानते हैं", "संस्कृत: 'नगरस्य रक्षिका देवी'", "कई लोग मानते हैं कि 'पटना' नाम इन्हीं देवी से पड़ा", "रक्षिका = रक्षा करने वाली"], "say": "पाठ के अंत में, पाटन देवी का उल्लेख है। पटना में, पाटन देवी का, बहुत प्राचीन मंदिर है। लोग इन्हें, नगर की रक्षा करने वाली देवी मानते हैं। संस्कृत में, नगरस्य रक्षिका देवी। रक्षिका शब्द का अर्थ है, रक्षा करने वाली। कई लोग यह भी मानते हैं, कि पटना नाम, इन्हीं देवी के नाम से पड़ा। यह प्रश्न भी आता है, कि पटना नगर की रक्षिका देवी कौन हैं। उत्तर है, पाटन देवी।"},
{"kind": "table", "icon": "📋", "head": "काल-क्रम: पाटलिपुत्र की यात्रा", "eq": "ढाई हज़ार साल — एक नज़र में", "rows": [["काल", "मुख्य बात"], ["बुद्ध काल", "पाटलिग्राम · 'महानगर बनेगा' की भविष्यवाणी"], ["चंद्रगुप्त मौर्य", "राजधानी · मेगास्थनीज़ का वर्णन"], ["अशोक", "वैभव और अधिक समृद्ध"], ["गुप्त काल", "कौमुदी महोत्सव · विद्या का केंद्र"], ["मध्यकाल", "वैभव घटा, मुग़ल काल में फिर उद्धार"], ["सिख इतिहास", "गुरु गोबिंद सिंह का जन्म"], ["आधुनिक काल", "बिहार की राजधानी · गाँधी सेतु, गोलघर, संग्रहालय"]], "say": "पाटलिपुत्र की, ढाई हज़ार साल की यात्रा, एक नज़र में देखिए। बुद्ध काल में, यह पाटलिग्राम था, और बुद्ध ने भविष्यवाणी की, कि यह महानगर बनेगा। चंद्रगुप्त मौर्य के समय, यह राजधानी था, और मेगास्थनीज़ ने इसका वर्णन किया। अशोक के समय, इसका वैभव और अधिक समृद्ध हुआ। गुप्त काल में, कौमुदी महोत्सव मनाया जाता था, और यह विद्या का केंद्र था। मध्यकाल में, वैभव घटा, और मुग़ल काल में फिर उद्धार हुआ। सिख इतिहास में, यह गुरु गोबिंद सिंह का जन्म-स्थान है। और आधुनिक काल में, यह बिहार की राजधानी है, जहाँ गाँधी सेतु, गोलघर और संग्रहालय हैं।"},
{"kind": "question", "icon": "🤔", "head": "सोचिए", "q": "बुद्ध ने जिन तीन ख़तरों (कलह, अग्नि, जल) की बात कही थी — आज हम उनसे अपने शहर-गाँव को कैसे बचा सकते हैं?", "a": "कलह: मिल-जुलकर रहना · अग्नि: आग से सावधानी · जल: बाँध-नाले की सफ़ाई, पेड़ लगाना, बाढ़ की तैयारी", "pause": 7, "say": "सोचिए। बुद्ध ने, जिन तीन ख़तरों की बात कही थी, कलह, अग्नि, और जल, आज हम उनसे, अपने शहर और गाँव को, कैसे बचा सकते हैं? ... कलह से बचने के लिए, सब धर्म और समाज के लोग, मिल-जुलकर रहें। अग्नि से बचने के लिए, बिजली और चूल्हे के साथ सावधानी बरतें। और जल, यानी बाढ़ से बचने के लिए, नालों की सफ़ाई रखें, पेड़ लगाएँ, और पहले से तैयारी रखें। ढाई हज़ार साल पुरानी चेतावनी, आज भी उतनी ही काम की है।"},
{"kind": "table", "icon": "📋", "head": "शब्दार्थ", "eq": "पाठ के ज़रूरी शब्द", "rows": [["संस्कृत शब्द", "हिंदी अर्थ"], ["वैभवम्", "शान, समृद्धि"], ["तीरे", "किनारे पर"], ["कलहः", "झगड़ा"], ["राजदूतः", "राजा का भेजा हुआ दूत"], ["समृद्धतरम्", "और अधिक समृद्ध"], ["कौमुदी", "चाँदनी"], ["महोत्सवः", "बड़ा उत्सव"], ["ख्यातिः", "प्रसिद्धि"], ["सेतुः", "पुल"], ["रक्षिका", "रक्षा करने वाली"], ["तीर्थस्थानम्", "पवित्र स्थान"]], "say": "पाठ के ज़रूरी शब्दार्थ। वैभवम्, शान, समृद्धि। तीरे, किनारे पर। कलहः, झगड़ा। राजदूतः, राजा का भेजा हुआ दूत। समृद्धतरम्, और अधिक समृद्ध। कौमुदी, चाँदनी। महोत्सवः, बड़ा उत्सव। ख्यातिः, प्रसिद्धि। सेतुः, पुल। रक्षिका, रक्षा करने वाली। और तीर्थस्थानम्, पवित्र स्थान।"},
{"kind": "table", "icon": "📋", "head": "व्याकरण", "eq": "संधि, समास, प्रत्यय", "rows": [["शब्द", "जानकारी"], ["महोत्सवः", "संधि-विच्छेद: महा + उत्सवः (गुण संधि)"], ["सचिवालयः", "सचिव + आलयः (दीर्घ संधि)"], ["सङ्ग्रहालयः", "सङ्ग्रह + आलयः (दीर्घ संधि)"], ["जैविकोद्यानम्", "जैविक + उद्यानम् (गुण संधि)"], ["पाटलिपुत्रवैभवम्", "पाटलिपुत्रस्य वैभवम् (षष्ठी तत्पुरुष समास)"], ["राजदूतः", "राज्ञः दूतः (षष्ठी तत्पुरुष समास)"], ["समृद्धतरम्", "समृद्ध + तरप् प्रत्यय"], ["स्थितम्", "स्था + क्त प्रत्यय"]], "say": "अब व्याकरण। पहले संधि-विच्छेद। महोत्सवः, यानी महा, और उत्सवः, यह गुण संधि है। सचिवालयः, यानी सचिव, और आलयः, यह दीर्घ संधि है। सङ्ग्रहालयः, यानी सङ्ग्रह, और आलयः, यह भी दीर्घ संधि है। जैविकोद्यानम्, यानी जैविक, और उद्यानम्, यह गुण संधि है। अब समास। पाटलिपुत्रवैभवम्, इसका विग्रह है, पाटलिपुत्रस्य वैभवम्, यह षष्ठी तत्पुरुष समास है। राजदूतः, इसका विग्रह है, राज्ञः दूतः, यह भी षष्ठी तत्पुरुष है। अब प्रत्यय। समृद्धतरम् में, तरप् प्रत्यय है। और स्थितम् में, स्था धातु, और क्त प्रत्यय है।"},
{"kind": "content", "icon": "🌾", "head": "हम सबका गौरव", "points": ["आर्यभट: पाटलिपुत्र के पास कुसुमपुर में रहकर 'आर्यभटीय' लिखा — शून्य, पृथ्वी का घूमना", "चाणक्य (कौटिल्य): यहीं 'अर्थशास्त्र' लिखा, चंद्रगुप्त के गुरु और मंत्री", "फ़ाह्यान (चीनी यात्री): गुप्त काल में पाटलिपुत्र आया, यहाँ के अस्पतालों और दान-शालाओं की तारीफ़ की", "आज: पटना में बड़े विश्वविद्यालय, अस्पताल, आईआईटी, एम्स — फिर से विद्या का केंद्र", "अपनी राजधानी को साफ़, सुंदर और शांत रखना — हमारा कर्तव्य"], "say": "पाठ के अलावा भी, पाटलिपुत्र के गौरव की, कई बातें हैं। महान गणितज्ञ आर्यभट ने, पाटलिपुत्र के पास कुसुमपुर में रहकर, अपना ग्रंथ आर्यभटीय लिखा, और बताया, कि पृथ्वी अपनी धुरी पर घूमती है। चाणक्य ने, यहीं अर्थशास्त्र लिखा, और वे चंद्रगुप्त के गुरु और मंत्री थे। चीनी यात्री फ़ाह्यान, गुप्त काल में पाटलिपुत्र आया, और उसने यहाँ के मुफ़्त अस्पतालों और दान-शालाओं की, बहुत तारीफ़ की। और आज, पटना में बड़े विश्वविद्यालय हैं, अस्पताल हैं, आई आई टी और एम्स हैं। यानी यह नगर, फिर से विद्या का केंद्र बन रहा है। अपनी राजधानी को, साफ़, सुंदर और शांत रखना, हम सबका कर्तव्य है।"},
{"kind": "list", "icon": "📝", "head": "सार", "points": ["पाटलिपुत्र = पटना, बिहार की राजधानी, गंगा के तीर पर · इतिहास ~2500 वर्ष", "बुद्ध: महानगर बनेगा; कलह, अग्नि, जल से भय · मेगास्थनीज़ ने शोभा का वर्णन किया", "गुप्त काल: शरद में कौमुदी महोत्सव · नाम: पुष्पपुर, कुसुमपुर", "राजशेखर (काव्यमीमांसा): यहाँ शास्त्रकारों की परीक्षा · दामोदर गुप्त (कुट्टनीमतम्)", "गुरु गोबिंद सिंह का जन्म · गाँधी सेतु, गोलघर, संग्रहालय · रक्षिका: पाटन देवी"], "say": "आज का सार। एक, पाटलिपुत्र, यानी पटना, बिहार की राजधानी है, गंगा के तीर पर है, और इसका इतिहास, लगभग ढाई हज़ार वर्ष का है। दो, बुद्ध ने कहा था, कि यह महानगर बनेगा, पर इसे कलह, अग्नि और जल से भय रहेगा, और मेगास्थनीज़ ने, इसकी शोभा का वर्णन किया। तीन, गुप्त काल में, शरद ऋतु में, कौमुदी महोत्सव मनाया जाता था, और इसके नाम, पुष्पपुर और कुसुमपुर भी थे। चार, राजशेखर ने काव्यमीमांसा में लिखा, कि यहाँ शास्त्रकारों की परीक्षा होती थी, और दामोदर गुप्त ने, कुट्टनीमतम् में इसका वर्णन किया। पाँच, यहाँ गुरु गोबिंद सिंह का जन्म हुआ, यहाँ गाँधी सेतु, गोलघर और संग्रहालय हैं, और नगर की रक्षिका, पाटन देवी हैं।"},
{"kind": "question", "icon": "❓", "head": "अभ्यास प्रश्न 1", "q": "पाटलिपुत्र किस नदी के किनारे स्थित है? यह किस राज्य की राजधानी है?", "a": "गंगा नदी · बिहार", "pause": 4, "say": "अब अभ्यास। वीडियो रोककर उत्तर सोचिए। पहला, पाटलिपुत्र किस नदी के किनारे स्थित है, और यह किस राज्य की राजधानी है? ... गंगा नदी के किनारे। बिहार की राजधानी।"},
{"kind": "question", "icon": "❓", "head": "अभ्यास प्रश्न 2", "q": "भगवान बुद्ध ने पाटलिग्राम के बारे में क्या कहा था?", "a": "यह महानगर बनेगा, पर इसे कलह, अग्नि और जल से भय रहेगा", "pause": 5, "say": "दूसरा, भगवान बुद्ध ने, पाटलिग्राम के बारे में क्या कहा था? ... कि यह महानगर बनेगा, पर इसे, कलह, अग्नि और जल से, भय रहेगा।"},
{"kind": "question", "icon": "❓", "head": "अभ्यास प्रश्न 3", "q": "चंद्रगुप्त मौर्य के समय कौन-सा विदेशी राजदूत पाटलिपुत्र आया था?", "a": "यूनान का राजदूत मेगास्थनीज़", "pause": 4, "say": "तीसरा, चंद्रगुप्त मौर्य के समय, कौन-सा विदेशी राजदूत, पाटलिपुत्र आया था? ... यूनान का राजदूत, मेगास्थनीज़।"},
{"kind": "question", "icon": "❓", "head": "अभ्यास प्रश्न 4", "q": "कौमुदी महोत्सव किस ऋतु में और किस काल में मनाया जाता था?", "a": "शरद ऋतु में · गुप्त काल में", "pause": 4, "say": "चौथा, कौमुदी महोत्सव, किस ऋतु में, और किस काल में मनाया जाता था? ... शरद ऋतु में, गुप्त काल में।"},
{"kind": "question", "icon": "❓", "head": "अभ्यास प्रश्न 5", "q": "पाटलिपुत्र के दो अन्य प्राचीन नाम क्या थे?", "a": "पुष्पपुर और कुसुमपुर", "pause": 4, "say": "पाँचवाँ, पाटलिपुत्र के, दो अन्य प्राचीन नाम क्या थे? ... पुष्पपुर, और कुसुमपुर।"},
{"kind": "question", "icon": "❓", "head": "अभ्यास प्रश्न 6", "q": "पटना में किस सिख गुरु का जन्म हुआ था?", "a": "दसवें गुरु — गुरु गोबिंद सिंह जी", "pause": 4, "say": "छठा, पटना में, किस सिख गुरु का जन्म हुआ था? ... दसवें गुरु, गुरु गोबिंद सिंह जी का।"},
